/**
 * @brief Function to initialize the GETH module as per the configuration made
 * in GUI.
 * @param handle Pointer to static content of APP configuration.
 * @return ETHERNET_CONFIG_STATUS_t: Status of the GETH driver initialization.\n
 *   @ref ETHERNET_CONFIG_STATUS_SUCCESS - on successful initialization.\n
 *   @ref ETHERNET_CONFIG_STATUS_FAILURE - if initialization fails.\n
 *
 * \par<b>Description:</b><br>
 * This function configures GETH registers based on the settings provided in the GUI.
 * <BR>
 *
 * \par<b>Example Usage</b><br>
 * @code
 * #include "Ifx_Types.h"
 * #include "IfxCpu.h"
 * #include "IfxScuWdt.h"
 * #include "ETHERNET_CONFIG/ethernet_config.h"
 *
 * IFX_ALIGN(4) IfxCpu_syncEvent g_cpuSyncEvent = 0;
 *
 * void core0_main(void)
 * {
 *   // !!WATCHDOG0 AND SAFETY WATCHDOG ARE DISABLED HERE!!
 *   // Enable the watchdogs and service them periodically if it is required
 *
 *   IfxScuWdt_disableCpuWatchdog(IfxScuWdt_getCpuWatchdogPassword());
 *   IfxScuWdt_disableSafetyWatchdog(IfxScuWdt_getSafetyWatchdogPassword());
 *
 *   // Wait for CPU sync event
 *   IfxCpu_emitEvent(&g_cpuSyncEvent);
 *   IfxCpu_waitEvent(&g_cpuSyncEvent, 1);
 *
 *   // Initialization of APP
 *   ETHERNET_CONFIG_STATUS_t status = ETHERNET_CONFIG_Init(&ETHERNET_CONFIG_0);
 *   if (status != ETHERNET_CONFIG_STATUS_SUCCESS) {
 *     while (1) {
 *       // Implement your code to handle the error here!
 *     }
 *   }
 *
 *   while (1);
 * }
 *
 * void DMA_Tx_UserCallback()
 * {
 * }
 *
 * void DMA_Rx_UserCallback()
 * {
 * }
 * @endcode
 * @note Normally this will be called automatically from DAVE_Init() that are located in core0_main().
 */
ETHERNET_CONFIG_STATUS_t ETHERNET_CONFIG_Init(ETHERNET_CONFIG_t *handle);

